// Editable, proportion-preserving 2D illustration assets for 小島生活任務.
// These scenes contain no game state, external requests, font dependencies or timers.
let serial=0;
const C={ink:'#41606c',skin:'#ffd7b0',cheek:'#ed9e87',hair:'#343c42',blue:'#7abbd0',deepBlue:'#3c809d',mint:'#b8d9c5',cream:'#fff9e9',amber:'#efbf65',wood:'#c79a69',coral:'#dd937d',grass:'#a9c99c'};
const alts={lamp:'客廳裏，小朋友按下開關，電線連着桌燈。',bell:'校園裏，上課鈴響起，小朋友走進課室。',wash:'小朋友回到家後，在洗手盆前洗手。',school:'放學後，小朋友由校門走回家。',ball:'活動場上，小朋友拍球，球落地後彈起。',wind:'公園裏，小朋友吹氣，面前的風車轉動。'};
export function sceneAlt(kind){return alts[kind]||'生活情境圖畫。';}
function star(x,y,s=1){return `<path d="m${x} ${y-12*s} ${4*s} ${8*s} ${9*s} ${1*s} ${-7*s} ${6*s} ${2*s} ${9*s} ${-8*s} ${-5*s} ${-8*s} ${5*s} ${2*s} ${-9*s} ${-7*s} ${-6*s} ${9*s} ${-1*s}z" fill="${C.amber}" stroke="none"/>`;}
function plant(x,y){return `<g transform="translate(${x} ${y})"><path d="M0 15V-36m0 15q-35-36-45-5Q-37-5 0-5m0-12q35-41 46-11Q36-8 0-4" fill="#91b69a" stroke="${C.ink}" stroke-width="4" stroke-linecap="round"/><path d="m-28 10 6 45h45l7-45z" fill="${C.coral}" stroke="${C.ink}" stroke-width="4"/></g>`;}
function cloud(x,y){return `<path d="M${x} ${y}q-20-30 10-40 20-40 48-8 34-11 37 20 29 3 24 28z" fill="#fffdf3" opacity=".94"/>`;}
function window(){return `<g stroke="#b79e75" stroke-width="5"><rect x="690" y="55" width="190" height="190" rx="10" fill="#e5f2ed"/><path d="M700 204q45-60 89-25 49-50 82-25v80H700z" fill="#b9d4ad" stroke="none"/><path d="M785 58v181M696 151h178" fill="none"/><path d="M682 48h28v204h-28m191-204h26v204h-26" fill="#f3dca4" stroke="#e3c88c"/></g>`;}
function indoor(mini=false){return `<rect width="960" height="540" fill="#e4f1e7"/><path d="M0 386h960v154H0z" fill="#f0d9b6"/><path d="M0 386h960" stroke="#d2b28b" stroke-width="9"/><path d="M30 451h900M45 505h860" stroke="#dec49e" stroke-width="3" opacity=".6"/>${mini?'':window()+plant(90,335)}`;}
function outdoor(mini=false){return `<rect width="960" height="540" fill="#d9eef0"/>${mini?'':cloud(80,115)+cloud(680,90)}<path d="M0 315Q140 238 275 304 447 239 589 305 785 240 960 309v231H0z" fill="#bcd4b4"/><path d="M0 391q210-40 444 0 255-42 516 0v149H0z" fill="#e9d8ad"/><path d="M0 475h960" stroke="#d4c094" stroke-width="4"/>`;}
// All actor proportions are authored once. Positioning uses translation only.
function boy(x,y,{pose='idle',walk=false,shirt=C.blue}={}){
 const right=pose==='press'?'<path class="sa-arm" d="M95 133q25-4 57-24"/>':pose==='wash'?'<path class="sa-arm" d="M94 135q28 7 58 6"/>':pose==='ball'?'<path class="sa-arm sa-dribble-arm" d="M94 133q28 3 52 17"/>':pose==='listen'?'<path class="sa-arm" d="M94 134q28-35 8-65"/>':'<path class="sa-arm" d="M94 134q17 32 10 58"/>';
 const left=pose==='wash'?'<path class="sa-arm" d="M25 134q33 30 113 12"/>':'<path class="sa-arm" d="M26 134q-13 33-8 57"/>';
 const mouth=pose==='blow'?'<ellipse cx="74" cy="79" rx="8" ry="9" fill="#a26054"/>':'<path d="M48 79q15 16 28 0" fill="#c66f61" stroke="#ae655a" stroke-width="3" stroke-linecap="round"/>';
 return `<g transform="translate(${x} ${y})"><g class="sa-actor ${walk?'sa-walking':''}"><g class="sa-body"><path d="M35 188 32 240" stroke="${C.skin}" stroke-width="22" stroke-linecap="round" class="sa-leg sa-leg-left"/><path d="m79 188 6 52" stroke="${C.skin}" stroke-width="22" stroke-linecap="round" class="sa-leg sa-leg-right"/><path d="M21 230h30l7 20q-16 12-46 4zM73 230h29l9 23q-27 10-42-3z" fill="${C.deepBlue}" stroke="${C.ink}" stroke-width="4" class="sa-shoes"/><path d="m26 178 1 29h28l4-24 4 24h29l-2-29z" fill="#426d85" stroke="${C.ink}" stroke-width="4"/><path d="m31 113-15 27 15 9v34h62v-35l14-10-13-25-24-10H52z" fill="${shirt}" stroke="${C.ink}" stroke-width="4" stroke-linejoin="round"/><path d="m51 102 9 16 14-16" fill="#fff8eb" stroke="${C.ink}" stroke-width="3"/><path d="M59 122v50" stroke="#fff5df" stroke-width="4"/><g fill="none" stroke="${C.skin}" stroke-width="16" stroke-linecap="round" stroke-linejoin="round">${left}${right}</g><ellipse cx="60" cy="58" rx="43" ry="49" fill="${C.skin}" stroke="${C.ink}" stroke-width="4"/><ellipse cx="17" cy="62" rx="9" ry="12" fill="${C.skin}"/><ellipse cx="103" cy="62" rx="9" ry="12" fill="${C.skin}"/><path d="M18 55Q1 6 45 9q8-14 23-7 20-12 33 17 24 7 4 42l-11-18-11-17q-2 24-23 27l3-21Q46 50 27 40z" fill="${C.hair}" stroke="${C.hair}" stroke-width="4" stroke-linejoin="round"/><ellipse cx="45" cy="62" rx="4" ry="6" fill="${C.hair}"/><ellipse cx="78" cy="62" rx="4" ry="6" fill="${C.hair}"/><ellipse cx="32" cy="76" rx="10" ry="6" fill="${C.cheek}" opacity=".65"/><ellipse cx="90" cy="76" rx="10" ry="6" fill="${C.cheek}" opacity=".65"/>${mouth}</g></g></g>`;
}
