function lampScene(active,mini){return `${indoor(mini)}<path d="M354 303v62q0 23 25 23h263" fill="none" stroke="#778f91" stroke-width="11" stroke-linecap="round"/>${active?'<path class="scene-result sa-cord-pulse" d="M354 303v62q0 23 25 23h263" fill="none" stroke="#f0c459" stroke-width="6" stroke-dasharray="20 18"/>':''}<g class="scene-cause" stroke="${C.ink}" stroke-width="5"><rect x="321" y="225" width="68" height="96" rx="12" fill="#7fb5c6"/><rect x="339" y="246" width="32" height="54" rx="5" fill="#fffaf0"/><path d="M343 ${active?285:256}h24" stroke="#c4cfca" stroke-width="5"/></g>${lamp(active)}${boy(169,211,{pose:'press'})}${active?star(840,319,.9):''}`;}
