function bellScene(active,mini){return `${indoor(true)}<path d="M0 144h475v230H0z" fill="#fff5db" stroke="#d7c9a7" stroke-width="5"/>${mini?'':'<rect x="67" y="197" width="220" height="116" rx="12" fill="#bed5c0" stroke="#91b29d" stroke-width="5"/><path d="M95 224h115m-115 28h158m-158 29h89" stroke="#f7f9ed" stroke-width="8" stroke-linecap="round"/>'}${classroomDoor()}${bellShape(650,108,active)}<g class="scene-cause ${active?'sa-enter-class':''}">${boy(314,216,{pose:active?'idle':'listen',walk:active})}</g>${active?'<path class="scene-result sa-direction-pulse" d="M465 430h55m-18-18 20 18-20 18" fill="none" stroke="#e2b257" stroke-width="9" stroke-linecap="round" stroke-linejoin="round"/>':''}`;}
