function washScene(active,mini){return `${indoor(true)}${homeDoor()}${mini?'':plant(859,375)}<g stroke="${C.ink}" stroke-width="5"><path d="M565 380h226v115H565z" fill="#c3dbd7"/><path d="M560 361h235l-17 58q-102 28-204 0z" fill="#f7fcf2"/><ellipse cx="678" cy="365" rx="108" ry="20" fill="#e4f1e8"/></g>${faucet(615,314)}${active?'<g class="scene-result sa-water-flow" fill="none" stroke="#70b9d2" stroke-width="8" stroke-linecap="round"><path d="M684 299v67"/><path d="M668 358q-14 11-26 0m57 0q16 11 28 0" stroke-width="5"/><path d="M679 306v54M690 310v47" stroke="#b7e2e9" stroke-width="3" stroke-dasharray="9 7"/></g>':''}<g class="scene-cause ${active?'sa-home-to-sink':''}">${boy(326,220,{pose:'wash',walk:active})}</g>${active?'<g class="scene-result sa-wash-bubbles" fill="#f5ffff" stroke="#91c9d3" stroke-width="3"><circle cx="645" cy="349" r="9"/><circle cx="663" cy="341" r="13"/><circle cx="681" cy="352" r="10"/><circle cx="668" cy="365" r="8"/></g>':''}`;}
function schoolBuilding(){return `<g stroke="${C.ink}" stroke-width="5" stroke-linejoin="round"><path d="M71 160h300v290H71z" fill="#fff5d9"/><path d="m40 170 180-99 180 99z" fill="#dc9a7e"/><path d="M99 206h62v64H99zm174 0h63v64h-63z" fill="#b1d7df"/><path d="M130 450V313h188v137" fill="#d2dfd0"/><path d="M181 313v137m87-137v137" fill="none"/><circle cx="220" cy="152" r="36" fill="#fff9e9"/><path d="M220 128v25l17 13" fill="none" stroke-linecap="round"/><path d="M51 450h344" stroke="#c4aa7f" stroke-width="14"/></g>`;}
function littleHome(){return `<g stroke="${C.ink}" stroke-width="5" stroke-linejoin="round"><path d="M650 249h225v211H650z" fill="#f8e5b8"/><path d="m620 255 140-107 142 107z" fill="#df9a82"/><path d="M735 334h64v126h-64z" fill="#8fbdc9"/><path d="M670 289h46v58h-46zm145 0h43v58h-43z" fill="#d7ede8"/><circle cx="786" cy="399" r="5" fill="#a4824b"/></g>`;}
function schoolScene(active,mini){return `${outdoor(mini)}<path d="M173 462q290 70 594 0" fill="none" stroke="#f9efd2" stroke-width="76"/>${schoolBuilding()}${littleHome()}<g class="scene-cause ${active?'sa-go-home':''}">${boy(278,228,{walk:active})}</g>${active?'<path class="scene-result sa-direction-pulse" d="M493 446h63m-18-18 20 18-20 18" fill="none" stroke="#dba84b" stroke-width="10" stroke-linecap="round" stroke-linejoin="round"/>':''}`;}
function basketball(x,y,cls=''){return `<g class="${cls}" transform="translate(${x} ${y})" stroke="${C.ink}" stroke-width="4"><circle r="34" fill="#eeb26c"/><path d="M-34 0h68M0-34v68M-24-24q30 24 0 48M24-24q-30 24 0 48" fill="none" stroke-width="3"/></g>`;}
function ballScene(active,mini){return `${outdoor(mini)}<path d="M64 383h832v118H64z" fill="#edc1a0" stroke="#cf9b7e" stroke-width="5"/><path d="M104 423h750M478 385v115" stroke="#fff5da" stroke-width="5"/><ellipse cx="478" cy="443" rx="92" ry="44" fill="none" stroke="#fff5da" stroke-width="5"/><g stroke="${C.ink}" stroke-width="5"><path d="M776 165v261" stroke-width="12"/><path d="M710 149h135v93H710z" fill="#f6f8e9"/><path d="M751 192h53v38h-53" fill="none" stroke="#c89069"/><ellipse cx="777" cy="241" rx="41" ry="10" fill="none" stroke="#d39173" stroke-width="7"/><path d="m744 248 10 56h48l10-56m-57 1 8 55m37-55-8 55" fill="none" stroke="#c8b993" stroke-width="3"/></g><g class="scene-cause">${boy(284,221,{pose:'ball'})}</g>${basketball(443,367,active?'scene-result sa-ball-bounce':'scene-result')}${active?'<ellipse class="sa-ball-shadow" cx="443" cy="492" rx="39" ry="8" fill="#aa8d7044"/><path class="sa-bounce-mark" d="m392 468-14-13m102 13 14-13" fill="none" stroke="#d99a4b" stroke-width="6" stroke-linecap="round"/>':''}`;}
function windmill(x,y,active){return `<g transform="translate(${x} ${y})"><path d="M0 0v216" stroke="${C.ink}" stroke-width="12" stroke-linecap="round"/><path d="M0 0v216" stroke="#ccad74" stroke-width="6" stroke-linecap="round"/><g class="${active?'sa-wheel-turn scene-result':''}" stroke="${C.ink}" stroke-width="4" stroke-linejoin="round"><path d="M0 0-84-25-29-83z" fill="#e8aa88"/><path d="M0 0 25-84 83-29z" fill="#e8c86d"/><path d="M0 0 84 25 29 83z" fill="#91c4c8"/><path d="M0 0-25 84-83 29z" fill="#a8c69d"/></g><circle r="13" fill="#fff3c9" stroke="${C.ink}" stroke-width="4"/></g>`;}
