function styles(scope){return `<style>
.${scope} .sa-walking .sa-body{animation:${scope}-gait .45s ease-in-out 7;transform-box:fill-box;transform-origin:50% 100%}
.${scope} .sa-enter-class .sa-walking .sa-body{animation-delay:.35s;animation-iteration-count:5}
.${scope} .sa-home-to-sink .sa-walking .sa-body{animation-iteration-count:3}
.${scope} .sa-lamp-glow{animation:${scope}-glow 1.8s ease-in-out infinite alternate}
.${scope} .sa-light-rays{animation:${scope}-glow 1.2s ease-in-out infinite alternate}
.${scope} .sa-cord-pulse{animation:${scope}-dash .9s linear infinite}
.${scope} .sa-bell-shake{animation:${scope}-ring .28s ease-in-out 7;transform-box:fill-box;transform-origin:50% 10%}
.${scope} .sa-sound-waves{animation:${scope}-glow .55s ease-in-out 5 alternate}
.${scope} .sa-enter-class{animation:${scope}-enter 2.1s .35s ease-in-out both}
.${scope} .sa-home-to-sink{animation:${scope}-sink 1.5s ease-in-out both}
.${scope} .sa-water-flow{animation:${scope}-water .7s 1.1s both}
.${scope} .sa-water-flow path{animation:${scope}-dash .65s linear infinite}
.${scope} .sa-wash-bubbles{animation:${scope}-bubbles 1.15s 1.1s ease-in-out infinite alternate}
.${scope} .sa-go-home{animation:${scope}-home 3.0s ease-in-out both}
.${scope} .sa-direction-pulse{animation:${scope}-glow 1s ease-in-out infinite alternate}
.${scope} .sa-ball-bounce{animation:${scope}-bounce 1.4s ease-in-out infinite}
.${scope} .sa-ball-shadow{animation:${scope}-shadow 1.4s ease-in-out infinite;transform-box:fill-box;transform-origin:center}
.${scope} .sa-dribble-arm{transform-box:fill-box;transform-origin:10% 0%}
.${scope}.sa-is-active .sa-dribble-arm{animation:${scope}-dribble 1.4s ease-in-out infinite}
.${scope} .sa-bounce-mark{animation:${scope}-impact 1.4s ease-in-out infinite}
.${scope} .sa-wheel-turn{animation:${scope}-wheel 2.3s linear infinite;transform-box:fill-box;transform-origin:center}
.${scope} .sa-air-flow{animation:${scope}-air .9s linear infinite}
.${scope}.sa-is-mini .sa-walking .sa-body{animation:none}
@keyframes ${scope}-gait{0%,100%{transform:rotate(-1deg) translateY(0)}50%{transform:rotate(1deg) translateY(-5px)}}
@keyframes ${scope}-glow{from{opacity:.54}to{opacity:1}}
@keyframes ${scope}-dash{to{stroke-dashoffset:-38}}
@keyframes ${scope}-ring{0%,100%{transform:rotate(-7deg)}50%{transform:rotate(7deg)}}
@keyframes ${scope}-enter{from{transform:translateX(0)}to{transform:translateX(256px)}}
@keyframes ${scope}-sink{from{transform:translateX(0)}to{transform:translateX(185px)}}
@keyframes ${scope}-water{from{opacity:0}to{opacity:1}}
@keyframes ${scope}-bubbles{from{opacity:.45;transform:translateY(1px)}to{opacity:1;transform:translateY(-5px)}}
@keyframes ${scope}-home{from{transform:translateX(0)}to{transform:translateX(360px)}}
@keyframes ${scope}-bounce{0%,100%{translate:0 0}34%{translate:0 87px}68%{translate:0 -37px}}
@keyframes ${scope}-shadow{0%,100%{opacity:.25;transform:scaleX(.65)}34%{opacity:.65;transform:scaleX(1)}68%{opacity:.14;transform:scaleX(.45)}}
@keyframes ${scope}-dribble{0%,100%{transform:rotate(-3deg)}30%{transform:rotate(15deg)}65%{transform:rotate(-8deg)}}
@keyframes ${scope}-impact{0%,22%,47%,100%{opacity:0}32%,36%{opacity:1}}
@keyframes ${scope}-wheel{to{transform:rotate(360deg)}}
@keyframes ${scope}-air{from{opacity:.3;transform:translateX(-6px)}to{opacity:.9;transform:translateX(10px)}}
</style>`;}
const builders={lamp:lampScene,bell:bellScene,wash:washScene,school:schoolScene,ball:ballScene,wind:windScene};
export function sceneArt(kind,{active=false,mini=false}={}){
 const safe=builders[kind]?kind:'lamp',scope=`sa-${safe}-${++serial}`;
 return `<svg class="scene-art ${scope}${active?' sa-is-active':''}${mini?' sa-is-mini':''}" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 960 540" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${sceneAlt(safe)}">${styles(scope)}${builders[safe](active,mini)}</svg>`;
}
