function choiceClassroom(){return `<g stroke="${C.ink}" stroke-width="5"><rect x="112" y="20" width="99" height="139" rx="6" fill="#d1e5d5"/><path d="M117 25h42v128h-42z" fill="#85b8ca"/><rect x="125" y="38" width="27" height="43" rx="3" fill="#eaf8ed"/><path d="M174 50h23v35h-23z" fill="#f4f4db"/><path d="M30 117h66m-18-17 19 17-19 17" fill="none" stroke="#dfb257" stroke-width="9" stroke-linecap="round" stroke-linejoin="round"/></g>`;}
