function choiceBall(){return `<path d="M49 151h146" stroke="#d6b996" stroke-width="6" stroke-linecap="round"/><g transform="translate(120 76)" stroke="${C.ink}" stroke-width="4"><circle r="39" fill="#ecaf6a"/><path d="M-39 0h78M0-39v78M-27-27q34 27 0 54M27-27q-34 27 0 54" fill="none" stroke-width="3"/></g><path d="M64 123q-14-45 2-65m-14 15 15-18 12 20" fill="none" stroke="#79a6b8" stroke-width="6" stroke-linecap="round" stroke-linejoin="round"/>`;}
function choiceWind(){return `<g transform="translate(135 77)" stroke="${C.ink}" stroke-width="4" stroke-linejoin="round"><path d="M0 0v83" stroke="#b59a6b" stroke-width="9"/><path d="M0 0-48-13-17-48z" fill="#e8aa88"/><path d="M0 0 13-48 48-17z" fill="#e8c86d"/><path d="M0 0 48 13 17 48z" fill="#91c4c8"/><path d="M0 0-13 48-48 17z" fill="#a8c69d"/><circle r="9" fill="#fff4cc"/></g><path d="M25 67q20-10 39-5m-33 23q26-7 42 2" fill="none" stroke="#83afbc" stroke-width="5" stroke-linecap="round"/>`;}
const choiceAliases={lightOn:'light',lamp:'light',doorbell:'bell',bellRing:'bell',waterFlow:'water',washHands:'wash',hands:'wash',goHome:'home',school:'classroom',enterClass:'classroom',ballBounce:'ball',pinwheel:'wind',windTurn:'wind'};
const choices={light:choiceLamp,bell:choiceBell,water:()=>choiceWater(false),wash:()=>choiceWater(true),classroom:choiceClassroom,home:choiceHome,ball:choiceBall,wind:choiceWind};
export function choiceArt(key){
 const k=choiceAliases[key]||key,draw=choices[k]||choiceLamp;
 return `<svg class="choice-art" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 240 180" preserveAspectRatio="xMidYMid meet" role="img" aria-label="選項情境圖畫"><rect x="3" y="3" width="234" height="174" rx="22" fill="#fffaf0"/>${draw()}</svg>`;
}
